"use strict";
import { MULTICALL_ADDRESSES, NONFUNGIBLE_POSITION_MANAGER_ADDRESSES as V3NFT_ADDRESSES } from "constants/addresses";
import { getAbstractContracts } from "uniswap/src/constants/abstractContracts";
import NFTPositionManagerJSON from "@uniswap/v3-periphery/artifacts/contracts/NonfungiblePositionManager.sol/NonfungiblePositionManager.json";
import MulticallJSON from "@uniswap/v3-periphery/artifacts/contracts/lens/UniswapInterfaceMulticall.sol/UniswapInterfaceMulticall.json";
import { useWeb3React } from "@web3-react/core";
import { RPC_PROVIDERS } from "constants/providers";
import { toContractInput } from "graphql/data/util";
import { useAccount } from "hooks/useAccount";
import { useMemo } from "react";
import {
  useUniswapPricesQuery
} from "uniswap/src/data/graphql/uniswap-data-api/__generated__/types-and-hooks";
import { useEnabledChains } from "uniswap/src/features/chains/hooks/useEnabledChains";
import { useIsSupportedChainIdCallback } from "uniswap/src/features/chains/hooks/useSupportedChainId";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { getContract } from "utilities/src/contracts/getContract";
import { currencyKey, currencyKeyFromGraphQL } from "utils/currencyKey";
function useContractMultichain(addressMap, ABI, chainIds) {
  const account = useAccount();
  const { provider: walletProvider } = useWeb3React();
  const isSupportedChain = useIsSupportedChainIdCallback();
  return useMemo(() => {
    const relevantChains = chainIds ?? Object.keys(addressMap).map((chainId) => parseInt(chainId)).filter((chainId) => isSupportedChain(chainId));
    return relevantChains.reduce((acc, chainId) => {
      const provider = walletProvider && account.chainId === chainId ? walletProvider : isSupportedChain(chainId) ? RPC_PROVIDERS[chainId] : void 0;
      const address = addressMap[chainId];
      if (provider && address) {
        acc[chainId] = getContract(address, ABI, provider);
      }
      return acc;
    }, {});
  }, [ABI, addressMap, chainIds, isSupportedChain, account.chainId, walletProvider]);
}
export function useV3ManagerContracts(chainIds) {
  const extendedAddresses = useMemo(() => {
    const addresses = { ...V3NFT_ADDRESSES };
    const abstractTestnetContracts = getAbstractContracts(UniverseChainId.Sepolia);
    if (abstractTestnetContracts?.nonfungiblePositionManager) {
      addresses[UniverseChainId.Sepolia] = abstractTestnetContracts.nonfungiblePositionManager;
    }
    const abstractMainnetContracts = getAbstractContracts(UniverseChainId.Mainnet);
    if (abstractMainnetContracts?.nonfungiblePositionManager) {
      addresses[UniverseChainId.Mainnet] = abstractMainnetContracts.nonfungiblePositionManager;
    }
    return addresses;
  }, []);
  return useContractMultichain(extendedAddresses, NFTPositionManagerJSON.abi, chainIds);
}
export function useInterfaceMulticallContracts(chainIds) {
  const extendedMulticallAddresses = useMemo(() => {
    const addresses = { ...MULTICALL_ADDRESSES };
    const multicall3Address = "0xcA11bde05977b3631167028862bE2a173976CA11";
    if (!addresses[UniverseChainId.Sepolia]) {
      addresses[UniverseChainId.Sepolia] = multicall3Address;
    }
    if (!addresses[UniverseChainId.Mainnet]) {
      addresses[UniverseChainId.Mainnet] = multicall3Address;
    }
    return addresses;
  }, []);
  return useContractMultichain(extendedMulticallAddresses, MulticallJSON.abi, chainIds);
}
export function usePoolPriceMap(positions) {
  const { defaultChainId } = useEnabledChains();
  const contracts = useMemo(() => {
    if (!positions || !positions.length) {
      return [];
    }
    const contractMap = positions.reduce((acc, { pool: { token0, token1 } }) => {
      acc[currencyKey(token0)] = toContractInput(token0, defaultChainId);
      acc[currencyKey(token1)] = toContractInput(token1, defaultChainId);
      return acc;
    }, {});
    return Object.values(contractMap);
  }, [defaultChainId, positions]);
  const { data, loading } = useUniswapPricesQuery({ variables: { contracts }, skip: !contracts.length });
  const priceMap = useMemo(
    () => data?.tokens?.reduce((acc, current) => {
      if (current) {
        acc[currencyKeyFromGraphQL(current)] = current.project?.markets?.[0]?.price?.value;
      }
      return acc;
    }, {}) ?? {},
    [data?.tokens]
  );
  return { priceMap, pricesLoading: loading && !data };
}
